    last_overdue_days_processed integer NOT NULL,
    CONSTRAINT ck_checkout_due_after_checkout CHECK ((due_date >= checked_out_at)),
    CONSTRAINT ck_checkout_renewal_count_non_negative CHECK ((renewal_count >= 0)),
    CONSTRAINT ck_checkout_return_after_checkout CHECK (((returned_at IS NULL) OR (returned_at >= checked_out_at)))
);


