--
-- Name: circulation_status_drift; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.circulation_status_drift AS
 SELECT ci.id,
    ci.title,
    ci.status AS item_status,
    c.status AS checkout_status,
    c.id AS checkout_id,
    c.user_id,
    c.checked_out_at,
    c.due_date
   FROM (public.catalog_items ci
     JOIN public.checkouts c ON (((c.item_id = ci.id) AND (c.status = 'active'::public.checkoutstatus))))
  WHERE (ci.status <> 'checked_out'::public.itemstatus);


--
-- Name: circulation_status_drift_reverse; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.circulation_status_drift_reverse AS
 SELECT id,
    title,
    status AS item_status
   FROM public.catalog_items ci
  WHERE ((status = 'checked_out'::public.itemstatus) AND (NOT (EXISTS ( SELECT 1
           FROM public.checkouts c
          WHERE ((c.item_id = ci.id) AND (c.status = 'active'::public.checkoutstatus))))));


