--
-- Name: indie_ebook_borrows; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.indie_ebook_borrows (
    id integer NOT NULL,
    ebook_id integer NOT NULL,
    user_id integer NOT NULL,
    borrowed_at timestamp with time zone DEFAULT now() NOT NULL,
    due_at timestamp with time zone NOT NULL,
    returned_at timestamp with time zone,
    status public.borrowstatus DEFAULT 'active'::public.borrowstatus NOT NULL,
    metislib_borrow_id integer,
    access_token character varying(64) NOT NULL,
    download_count integer DEFAULT 0 NOT NULL,
    max_downloads integer DEFAULT 5 NOT NULL,
    rating integer,
    review_text text,
    review_submitted_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    due_soon_notified_at timestamp with time zone,
    renewal_count integer DEFAULT 0 NOT NULL,
    CONSTRAINT ck_borrow_return_after_borrow CHECK (((returned_at IS NULL) OR (returned_at >= borrowed_at))),
    CONSTRAINT ck_download_count_non_negative CHECK ((download_count >= 0)),
    CONSTRAINT ck_max_downloads_positive CHECK ((max_downloads > 0)),
    CONSTRAINT ck_renewal_count_range CHECK (((renewal_count >= 0) AND (renewal_count <= 1))),
    CONSTRAINT indie_ebook_borrows_rating_check CHECK (((rating IS NULL) OR ((rating >= 1) AND (rating <= 5))))
);


